CREATE DATABASE CustomerChurnDB;

USE CustomerChurnDB;

CREATE TABLE CustomerSubscriptions (
    CustomerID VARCHAR(20) PRIMARY KEY,
    Name VARCHAR(100),
    Age INT,
    Gender VARCHAR(10),
    SubscriptionType VARCHAR(20),
    SubscriptionDate DATE,
    LastLoginDate DATE,
    TotalSessions INT,
    FeedbackScore INT,
    IsChurned INT
);

select * from CustomerSubscriptions;

delete from CustomerSubscriptions where CustomerID = 'CUST00001';


-- ---------------------- queres ---------------- >>>

-- quere 1 

SELECT
    SubscriptionType,
    IsChurned,
    COUNT(*) AS TotalCustomers
FROM CustomerSubscriptions
GROUP BY SubscriptionType, IsChurned
ORDER BY SubscriptionType;

-- quere 2

SELECT
    SubscriptionType,
    Gender,
    ROUND(AVG(FeedbackScore),2) AS AvgFeedback
FROM CustomerSubscriptions
GROUP BY SubscriptionType, Gender
ORDER BY SubscriptionType;

-- quere 3

SELECT *
FROM CustomerSubscriptions
WHERE TotalSessions < 5
AND FeedbackScore < 5;

-- quere 4

SELECT *
FROM CustomerSubscriptions
WHERE DATEDIFF(CURDATE(), LastLoginDate) > 60;

SELECT *
FROM CustomerSubscriptions WHERE DATEDIFF(DAY, LastLoginDate, GETDATE()) > 60;

-- quere 5

SELECT
    SubscriptionType,
    ROUND(
        SUM(IsChurned) * 100.0 / COUNT(*),
        2
    ) AS ChurnRate
FROM CustomerSubscriptions
GROUP BY SubscriptionType;

SELECT
    CustomerID,
    Name,
    DATEDIFF(CURDATE(), SubscriptionDate) AS SubscriptionDays
FROM CustomerSubscriptions
ORDER BY SubscriptionDays DESC
LIMIT 10;

-- quere 6

SELECT top 10 from CustomerID,
    Name,
    DATEDIFF(DAY, SubscriptionDate, GETDATE()) AS SubscriptionDays
FROM CustomerSubscriptions
ORDER BY SubscriptionDays DESC;

-- quere 7

SELECT
CASE
    WHEN Age BETWEEN 18 AND 25 THEN '18-25'
    WHEN Age BETWEEN 26 AND 35 THEN '26-35'
    WHEN Age BETWEEN 36 AND 45 THEN '36-45'
    WHEN Age BETWEEN 46 AND 55 THEN '46-55'
    ELSE '56+'
END AS AgeGroup,

COUNT(*) AS Customers,

ROUND(
SUM(IsChurned)*100.0/COUNT(*),
2
) AS ChurnRate

FROM CustomerSubscriptions

GROUP BY AgeGroup
ORDER BY AgeGroup;



SELECT COUNT(*) FROM CustomerSubscriptions;

SELECT COUNT(*)
FROM CustomerSubscriptions
WHERE IsChurned = 1;
